/* ── Tokens ── GENERATED from src/tokens.ts. Do not edit by hand. */
:root {
  --bg: #FAF8F2;                        /* paper */
  --text: #1A1A1A;                      /* ink */
  --text-secondary: #6B6B6B;            /* gray */
  --accent: #1A1A1A;                   /* the "accent" is ink; monochrome */
  --divider: rgba(0,0,0,0.08);
  --divider-subtle: rgba(0,0,0,0.06);
  --table-alt: rgba(0,0,0,0.02);
  --grid-line: rgba(0,0,0,0.04);
  --control-border: rgba(0,0,0,0.42);
  --control-fill: #E4E2DC;
  color-scheme: light;
  --radius-sm: 4px;           /* slight Vlak radius; standalone buttons */
  --radius: var(--radius-sm);              /* alias — buttons, boxes, dialogs share it; cards stay 0 */
  --radius-chrome: 0px;
  --gutter: 20px;
  --pad: 20px;
  /* Concentric: Steve Ruiz innerRadius result. Closed form of the circular-corner fit. Default radius vs --pad is 0. */
  --radius-in: max(0px, calc(var(--radius) - var(--pad)));
  --ease: cubic-bezier(0.3, 0, 0.2, 1);
  --duration-snap: 0.1s;
  --duration: 0.2s;
  --duration-deliberate: 0.4s;
  --duration-confirm: 0.3s;
  /* The hover transition every control shares: fill, edge, ink, opacity. */
  --transition: background-color var(--duration) var(--ease), border-color var(--duration) var(--ease), color var(--duration) var(--ease), opacity var(--duration) var(--ease);
  /* Background column grid: 204px modules (184 column + 20 gutter). */
  --grid-image: linear-gradient(to right,var(--grid-line) 0,var(--grid-line) 1px,transparent 1px,transparent 184px,var(--grid-line) 184px,var(--grid-line) 185px,transparent 185px,transparent 204px);
  --grid-size: 204px;
  --grid-pos: 20px 0;
  --text-scale: 1;
  /* Stacking scale. Native dialog and popover use the top layer instead. */
  --z-raised: 10;
  --z-sticky: 100;
  --z-float: 200;
  --z-overlay: 300;
  --z-toast: 400;
  /* Contract variables a component may set inline: concentric radius and the chart spot color. */
  --rs-out: var(--radius);
  --rs-gap: var(--pad);
  --rs-in: var(--radius-in);
  --rs-chart-spot: var(--text);
  /* Control scale. Every interactive target is at least 44px; phone fields use 16px type. */
  --hit: 2.75rem;
  --control-h: 2.75rem;
  --control-fs: 0.875rem;
  --control-label: 0.75rem;
}
[data-theme="dark"] {
  --bg: #0E0C0A;
  --text: #E8E8E8;
  --text-secondary: #949494;
  --accent: #E8E8E8;
  --divider: rgba(255,255,255,0.10);
  --divider-subtle: rgba(255,255,255,0.07);
  --table-alt: rgba(255,255,255,0.03);
  --grid-line: rgba(255,255,255,0.05);
  --control-border: rgba(255,255,255,0.38);
  --control-fill: #242220;
  color-scheme: dark;
}
/* System dark scheme applies until the page decides with data-theme. */
@media (prefers-color-scheme: dark) {
:root:not([data-theme="light"]) {
  --bg: #0E0C0A;
  --text: #E8E8E8;
  --text-secondary: #949494;
  --accent: #E8E8E8;
  --divider: rgba(255,255,255,0.10);
  --divider-subtle: rgba(255,255,255,0.07);
  --table-alt: rgba(255,255,255,0.03);
  --grid-line: rgba(255,255,255,0.05);
  --control-border: rgba(255,255,255,0.38);
  --control-fill: #242220;
  color-scheme: dark;
}
}
/* Mobile grid (≤480): two fluid columns, three 25px gutters
   (edge · middle · edge). Column width = 50vw − 37.5px; the background
   draws all four column-edge lines and content lives between the outer pair. */
@media(max-width:480px){
  :root{
    --pad:25px;
    --grid-image:linear-gradient(to right,transparent 0,transparent 25px,var(--grid-line) 25px,var(--grid-line) 26px,transparent 26px,transparent calc(50vw - 12.5px),var(--grid-line) calc(50vw - 12.5px),var(--grid-line) calc(50vw - 11.5px),transparent calc(50vw - 11.5px),transparent calc(50vw + 12.5px),var(--grid-line) calc(50vw + 12.5px),var(--grid-line) calc(50vw + 13.5px),transparent calc(50vw + 13.5px),transparent calc(100vw - 26px),var(--grid-line) calc(100vw - 26px),var(--grid-line) calc(100vw - 25px),transparent calc(100vw - 25px));
    --grid-size:100vw;
    --grid-pos:0 0;
  }
}
/* Phone control scale (≤640): keep 44px hits and use 16px type on fields. */
@media(max-width:640px){
  :root{
    --hit:2.75rem;
    --control-h:2.75rem;
    --control-fs:1rem;
    --control-label:0.9375rem;
  }
}

/* ── Base ──
   Vlak owns the page: paper on html, ink on body, and quiet
   gutter verticals on html::before so overflow-x:clip cannot drop
   them. --grid-pos: 20px 0 puts the first tile line on the left
   20px gutter; that utmost left gutter must paint. Do not clip
   it. No 204 horizontals — those cage the type. Homepage and
   About kill this overlay and keep boxed cells only. */
/* --text-scale multiplies the root size, so every rem in the system (type,
   controls, spacing inside components) follows it while the px module grid
   stays put. Browser text settings still apply underneath. */
html{scroll-behavior:smooth;overflow-x:clip;background-color:var(--bg);font-size:calc(100% * var(--text-scale, 1))}
html::before{
  content:"";
  position:fixed;
  inset:0;
  z-index:0;
  pointer-events:none;
  background-image:var(--grid-image);
  background-size:var(--grid-size) 100%;
  background-repeat:repeat-x;
  background-position:var(--grid-pos)
}
body{
  position:relative;
  z-index:1;
  overflow-x:clip;
  background-color:transparent;
  color:var(--text);
  font-family:Inter,-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;
  font-weight:500;
  line-height:1.45;
  transition:var(--transition);
  -webkit-font-smoothing:antialiased;
}

/* ── Utilities ── */
.rs-sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.rs-sr:focus-visible+.rs-check,.rs-sr:focus-visible+.rs-radio-dot,.rs-sr:focus-visible+.rs-switch{outline:1.5px solid var(--text);outline-offset:2px}

/* ── Type scale ──
   Hierarchy from weight, color, and position; never all caps.
   Sizes are rem: --text-scale on the root scales them with everything else. */
.rs-t-xl{font-size:clamp(2.125rem,5vw,3.25rem);font-weight:600;letter-spacing:-.035em;line-height:1.05;color:var(--text);margin:0;text-wrap:balance}
.rs-t-display{font-size:2.375rem;font-weight:600;letter-spacing:-.03em;line-height:1.15;color:var(--text);margin:0;text-wrap:balance}
.rs-t-title{font-size:1.375rem;font-weight:600;letter-spacing:-.02em;line-height:1.3;color:var(--text);margin:0;text-wrap:balance}
.rs-t-sub{font-size:1.0625rem;font-weight:500;letter-spacing:-.01em;line-height:1.45;color:var(--text-secondary);margin:0;text-wrap:pretty}
.rs-t-body{font-size:0.9375rem;font-weight:500;letter-spacing:-.01em;line-height:1.45;color:var(--text);margin:0;max-width:66ch;text-wrap:pretty}
.rs-t-label{font-size:0.8125rem;font-weight:600;letter-spacing:-.01em;line-height:1.3;color:var(--text);margin:0}

/* ── Inline code ── */
.rs-code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.88em;color:var(--text);background:var(--table-alt);padding:1px 5px;border-radius:var(--radius-sm);letter-spacing:0}

/* Reserved compatibility layer. Hover capability, press feedback, and overlay
   reveal now live in their component leaves. Keeping paint out of this later
   layer prevents touch resets from overriding selected or disabled states. */

/* ── Reduced motion: nothing loops, nothing slides, nothing enters ── */
@media(prefers-reduced-motion:reduce){
  .rs-reveal,.rs-crumb-bar .rs-crumbs,.rs-tip::after,.rs-hover-card-panel{transition:none}
  .rs-subscribed,.rs-toast{animation:none}
  .rs-theme-sun,.rs-theme-moon{transition:none}
  .rs-spinner svg{animation:none}
}
